"""Nonpainting complete original paragraph text-node and box observation."""
JS=r'''()=>{const g=window.evalViewer.graph,rows=[];window.__nativeParagraphProbeNodes=[];for(const cell of Object.values(g.model.cells)){const state=g.view.getState(cell);if(!cell.id.startsWith('source_paragraph_owner_')||!state?.text?.node)continue;const template=document.createElement('div');template.innerHTML=Graph.sanitizeHtml(g.getLabel(cell));const expected=template.firstElementChild;if(!expected)continue;const tree=n=>n.nodeType===3?['text',n.textContent]:n.nodeType===1?[n.tagName,[...n.childNodes].filter(c=>c.nodeType===1||c.nodeType===3).map(tree)]:null;const expectedTree=JSON.stringify(tree(expected));const matches=[...state.text.node.querySelectorAll(expected.tagName)].filter(e=>JSON.stringify(tree(e))===expectedTree);if(matches.length!==1){rows.push({cell:cell.id,unbound:true,matches:matches.length,expectedMarkup:template.innerHTML,actualMarkup:state.text.node.innerHTML});continue;}const root=matches[0];const b=root.getBoundingClientRect(),walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),runs=[];while(walk.nextNode()){const n=walk.currentNode,c=getComputedStyle(n.parentElement),chars=[];for(const{segment,index}of new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(n.textContent)){const r=document.createRange();r.setStart(n,index);r.setEnd(n,index+segment.length);const b=r.getBoundingClientRect();chars.push({text:segment,start:index,rectCount:r.getClientRects().length,x:b.x,y:b.y,width:b.width,height:b.height});}n.parentElement.setAttribute('data-paragraph-probe-node',String(window.__nativeParagraphProbeNodes.length));runs.push({text:n.textContent,child_index:[...n.parentNode.childNodes].indexOf(n),nodeIndex:window.__nativeParagraphProbeNodes.length,selector:'[data-paragraph-probe-node="'+window.__nativeParagraphProbeNodes.length+'"]',css:Object.fromEntries(['font-family','font-size','font-weight','font-style','font-synthesis','font-kerning','font-feature-settings','font-variation-settings','font-variant-ligatures','white-space','line-height','vertical-align','color','-webkit-text-fill-color','text-rendering'].map(k=>[k,c.getPropertyValue(k)])),chars});window.__nativeParagraphProbeNodes.push(n);}for(const run of runs)run.selector='[data-paragraph-probe-node="'+window.__nativeParagraphProbeNodes[run.nodeIndex].parentElement.getAttribute('data-paragraph-probe-node')+'"]';rows.push({cell:cell.id,rootRect:{x:b.x,y:b.y,width:b.width,height:b.height},markup:root.outerHTML,runs});}return rows;}'''
def observe(page):
 from html_source_text_node_binding_v9 import physical_fonts_for_object
 rows=page.evaluate(JS);session=page.context.new_cdp_session(page);session.send('DOM.enable',{'includeWhitespace':'all'});session.send('CSS.enable');root=session.send('DOM.getDocument',{'depth':1})['root']['nodeId']
 try:
  for row in rows:
   for run in row.get('runs',[]):
    node=session.send('DOM.querySelector',{'nodeId':root,'selector':run['selector']})['nodeId'];obj=session.send('Runtime.evaluate',{'expression':'window.__nativeParagraphProbeNodes['+str(run['nodeIndex'])+']','returnByValue':False})['result']
    try:run['actual_fonts'],run['actual_original_Text_backend_binding']=physical_fonts_for_object(session,obj['objectId'],node,run['child_index'],run['text'])
    finally:session.send('Runtime.releaseObject',{'objectId':obj['objectId']})
 finally:session.detach()
 return rows

def observe_rectangles(page):
 return page.evaluate('''()=>{const rows=[],g=window.evalViewer.graph;for(const cell of Object.values(g.model.cells)){if(!cell.vertex)continue;const s=g.view.getState(cell),style=g.getCellStyle(cell);if(!s?.shape?.node||style.shape==='text'||style.shape==='image'||!(s.shape instanceof mxRectangleShape))continue;const b=s.shape.node.getBBox(),m=s.shape.node.getScreenCTM(),points=[[b.x,b.y],[b.x+b.width,b.y],[b.x,b.y+b.height],[b.x+b.width,b.y+b.height]].map(([x,y])=>({x:m.a*x+m.c*y+m.e,y:m.b*x+m.d*y+m.f}));if(Math.abs(m.a-1)>1e-12||Math.abs(m.d-1)>1e-12||Math.abs(m.b)>1e-12||Math.abs(m.c)>1e-12)throw Error('SOURCE_rect_nontranslation_native_CTM');rows.push({cell:cell.id,native_geometric_path_box:{x:Math.min(...points.map(p=>p.x)),y:Math.min(...points.map(p=>p.y)),width:Math.max(...points.map(p=>p.x))-Math.min(...points.map(p=>p.x)),height:Math.max(...points.map(p=>p.y))-Math.min(...points.map(p=>p.y))},actual_SVG_screen_offset:s.shape.getSvgScreenOffset(),model_geometry:{x:cell.geometry.x,y:cell.geometry.y,width:cell.geometry.width,height:cell.geometry.height},stroke_width:s.shape.strokewidth,fill:s.shape.fill,stroke:s.shape.stroke,actual_SVG_markup:s.shape.node.outerHTML,official_getSvgScreenOffset_source:mxShape.prototype.getSvgScreenOffset.toString()});}return rows;}''')
